// src/App.tsx
import React from 'react';
import {
  BrowserRouter as Router,
  Route,
  Switch,
  useParams,
} from 'react-router-dom';
import './App.css';
import Slides from './Slides';

const SlidesRoute: React.FC = () => {
  const { person_id } = useParams<{ person_id: string }>();
  return <Slides personId={person_id} />;
