internal class XmlSchemaFilter
{
    public XmlSchemaSet FilterSchema(XmlSchemaSet inputSchemas, List<JhaContractTypeInfo> contractTypes)
    {
        var outputSchemas = new XmlSchemaSet();
        var outputSchema = new XmlSchema();

        var rootTypes = contractTypes.Select(t => t.ClassName).ToList();
        var visitedTypes = new HashSet<string>();

        foreach (var schema in inputSchemas.Schemas().OfType<XmlSchema>())
        {
            foreach (var item in schema.Items.OfType<XmlSchemaObject>())
            {
                if (item is XmlSchemaElement element)
                {
                    if (rootTypes.Contains(element.ElementSchemaType!.Name))
                    {
                        outputSchema.Items.Add(element);
                        EnumerateDeep(element.ElementSchemaType, schema, visitedTypes, outputSchema);
                    }
                }
                else if (item is XmlSchemaComplexType complexType)
                {
                    if (rootTypes.Contains(complexType.Name))
                    {
                        outputSchema.Items.Add(complexType);
                        EnumerateDeep(complexType, schema, visitedTypes, outputSchema);
                    }
                }
            }
        }

        outputSchemas.Add(outputSchema);
        return outputSchemas;
    }

    private void EnumerateDeep(XmlSchemaType type, XmlSchema schema, HashSet<string> visitedTypes, XmlSchema outputSchema)
    {
        if (type == null || visitedTypes.Contains(type.Name))
        {
            return;
        }

        visitedTypes.Add(type.Name);

        if (type is XmlSchemaComplexType complexType)
        {
            foreach (var attribute in complexType.AttributeUses.Values.OfType<XmlSchemaAttribute>())
            {
                EnumerateDeep(attribute.AttributeSchemaType, schema, visitedTypes, outputSchema);
            }

            if (complexType.ContentTypeParticle is XmlSchemaGroupBase groupBase)
            {
                foreach (var particle in groupBase.Items.OfType<XmlSchemaParticle>())
                {
                    if (particle is XmlSchemaElement element)
                    {
                        EnumerateDeep(element.ElementSchemaType, schema, visitedTypes, outputSchema);
                    }
                    else if (particle is XmlSchemaGroupRef groupRef)
                    {
                        EnumerateDeep(groupRef.Particle, schema, visitedTypes, outputSchema);
                    }
                }
            }
        }
    }
}
