  for (int i = 0; i < letterArrIndex; i++) {
    // increment the count for the letter at the corresponding index in the array
    letterCounts[letterArr[i] - 'a']++;
  }

  // iterate through the elements in the letterCounts array
  for (int i = 0; i < 26; i++) {
